import { MakeLogicType, afterMount, connect, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { loopsList } from '../generated/api'
import type { LoopDTOApi, PaginatedLoopDTOListApi } from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface loopsLogicValues {
    currentTeamId: number | null // teamLogic
    atLoopLimit: boolean
    loops: LoopDTOApi[] | null
    loopsFailed: boolean
    loopsPage: PaginatedLoopDTOListApi | null
    loopsPageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface loopsLogicActions {
    loadLoopsPage: () => any
    loadLoopsPageFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadLoopsPageSuccess: (
        loopsPage: PaginatedLoopDTOListApi | null,
        payload?: any
    ) => {
        loopsPage: PaginatedLoopDTOListApi | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface loopsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        loops: (loopsPage: PaginatedLoopDTOListApi | null) => LoopDTOApi[] | null
        atLoopLimit: (loopsPage: PaginatedLoopDTOListApi | null) => boolean
    }
}

export type loopsLogicType = MakeLogicType<loopsLogicValues, loopsLogicActions, Record<string, any>, loopsLogicMeta>

/** The loops the current user can see in this project. A loop scene reloads it after each change. */
export const loopsLogic = kea<loopsLogicType>([
    path(['products', 'tasks', 'loops', 'loopsLogic']),
    connect(() => ({ values: [teamLogic, ['currentTeamId']] })),
    loaders(({ values }) => ({
        loopsPage: [
            null as PaginatedLoopDTOListApi | null,
            {
                loadLoopsPage: async () =>
                    values.currentTeamId ? await loopsList(String(values.currentTeamId), { limit: 100 }) : null,
            },
        ],
    })),
    reducers({
        loopsFailed: [
            false,
            {
                loadLoopsPage: () => false,
                loadLoopsPageSuccess: () => false,
                loadLoopsPageFailure: () => true,
            },
        ],
    }),
    selectors({
        // `null` until the first load answers, so the sidebar never shows the empty state too early.
        loops: [
            (s) => [s.loopsPage],
            (loopsPage: PaginatedLoopDTOListApi | null): LoopDTOApi[] | null =>
                loopsPage ? [...loopsPage.results].sort((a, b) => a.name.localeCompare(b.name)) : null,
        ],
        atLoopLimit: [
            (s) => [s.loopsPage],
            (loopsPage: PaginatedLoopDTOListApi | null): boolean =>
                loopsPage?.max_loops_per_team !== undefined &&
                (loopsPage.total_loop_count ?? 0) >= loopsPage.max_loops_per_team,
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadLoopsPage()
    }),
])
